    InstalledType {
        unmarshallable_spec: |v: Value| T::unmarshal_spec(v) is Ok,
        unmarshallable_status: |v: Value| T::unmarshal_status(v) is Ok,
        valid_object: |obj: DynamicObjectView| T::unmarshal(obj)->Ok_0.state_validation(),
