///
/// Note in particular that `self == self.sub(m).add(m)` only holds if
/// `m` is included in `self`.
pub uninterp spec fn sub(self, m2: Self) -> Self;

/// Inserts one instance the value `v` into the multiset.
///
/// This always increases the total size of the multiset by 1.
pub open spec fn insert(self, v: V) -> Self {
    self.add(Self::singleton(v))
}

/// Removes one instance of the value `v` from the multiset.
///
/// If `v` was absent from the multiset, then the multiset is unchanged.
pub open spec fn remove(self, v: V) -> Self {
    self.sub(Self::singleton(v))
}

/// Updates the multiplicity of the value `v` in the multiset to `mult`.
pub open spec fn update(self, v: V, mult: nat) -> Self {
    let map = Map::new(
        |key: V| (self.contains(key) || key == v),
        |key: V|
            if key == v {
                mult
            } else {
                self.count(key)
            },
    );
    Self::from_map(map)
}

/// Returns `true` is the left argument is contained in the right argument,
/// that is, if for each value `v`, the number of occurences in the left
/// is at most the number of occurences in the right.

pub open spec fn update_pod() -> PodMonkeyAction {
    Action {
        precondition: |input: PodMonkeyActionInput, s: ()| {
            true
        },
        transition: |input: PodMonkeyActionInput, s: ()| {
            let update_req_msg = pod_monkey_req_msg(
                input.rpc_id_allocator.allocate().1,
                update_req_msg_content(
                    input.pod.metadata.namespace->0,
                    input.pod.metadata.name->0,
                    input.pod.marshal()
                )
            );

            let s_prime = s;
            let output = PodMonkeyActionOutput {
                send: Multiset::singleton(update_req_msg),
                rpc_id_allocator: input.rpc_id_allocator.allocate().0,
            };
            (s_prime, output)
        },
    }
}

pub open spec fn update_pod_status() -> PodMonkeyAction {
    Action {
        precondition: |input: PodMonkeyActionInput, s: ()| {
            true
        },
        transition: |input: PodMonkeyActionInput, s: ()| {
            let update_status_req_msg = pod_monkey_req_msg(
                input.rpc_id_allocator.allocate().1,
                update_status_req_msg_content(
                    input.pod.metadata.namespace->0,
                    input.pod.metadata.name->0,
                    input.pod.marshal()
                )
            );

            let s_prime = s;
            let output = PodMonkeyActionOutput {
                send: Multiset::singleton(update_status_req_msg),
                rpc_id_allocator: input.rpc_id_allocator.allocate().0,
            };
            (s_prime, output)
        },
    }
}

pub open spec fn pod_monkey() -> PodMonkeyStateMachine {
    StateMachine {
        init: |s: ()| {
            true
        },
        actions: set![create_pod(), delete_pod(), update_pod(), update_pod_status()],
        step_to_action: |step: PodMonkeyStep| {
            match step {
                PodMonkeyStep::CreatePod => create_pod(),
                PodMonkeyStep::UpdatePod => update_pod(),
                PodMonkeyStep::UpdatePodStatus => update_pod_status(),
                PodMonkeyStep::DeletePod => delete_pod(),
            }
        },
        action_input: |step: PodMonkeyStep, input: PodMonkeyActionInput| {
            input
        }
    }
}

